<?= csrf() ?><input type="hidden" name="version" value="<?= (int)$t['version'] ?>">
<?php $readOnly=$user['role']==='viewer'||$t['archived'];$selected=array_map('intval',array_column($people,'id')); ?>
<p class="help-text">Affectez le travail à un responsable principal, à des collaborateurs et, si besoin, à une équipe responsable. L’ajout ne change pas les droits d’accès au projet.</p>
<label>Responsable principal<select name="assignee_id" <?= $readOnly?'disabled':'' ?>><option value="">Non assigné</option><?php foreach($members as $person): ?><option value="<?= (int)$person['id'] ?>" <?= (int)$t['assignee_id']===(int)$person['id']?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach; ?></select></label>
<label>Équipe responsable<select name="team_id" <?= $readOnly?'disabled':'' ?>><option value="">Sans équipe</option><?php foreach($teams as $team): ?><option value="<?= (int)$team['id'] ?>" <?= (int)$t['team_id']===(int)$team['id']?'selected':'' ?>><?= e($team['name']) ?></option><?php endforeach; ?></select></label>
<fieldset class="people-collaborators"><legend>Collaborateurs assignés</legend><label>Rechercher une personne<input type="search" data-people-search data-dialog-ignore placeholder="Nom ou adresse e-mail"></label><div class="people-candidates"><?php foreach($members as $person): ?><label class="check-label" data-person-search="<?= e(mb_strtolower($person['name'].' '.$person['email'])) ?>"><input type="checkbox" name="collaborators[]" value="<?= (int)$person['id'] ?>" <?= in_array((int)$person['id'],$selected,true)?'checked':'' ?> <?= $readOnly?'disabled':'' ?>><?= avatar($person['name'],'small',(int)$person['id']) ?><span><?= e($person['name']) ?></span></label><?php endforeach; ?></div><small>Le responsable n’est pas ajouté une seconde fois comme collaborateur. Le suivi des notifications reste géré séparément.</small></fieldset>
<?php if(!$readOnly): ?><button type="submit" class="button primary">Enregistrer les personnes</button><?php else: ?><p class="help-text">Consultation uniquement<?= $t['archived']?' : ticket archivé':'' ?>.</p><?php endif; ?>
